=== FILE: rr_arbiter.v ===
// rr_arbiter.v
// Round-robin arbiter for N requesters (interface_spec.md, microarchitecture.md).
// State: one priority pointer `ptr`, $clog2(N) bits, reset to 0.
// Grant: combinational wrapping priority search from `ptr`, wrap at N-1.
// Update: on a rising edge with a grant, ptr <= winner + 1 (wrapping at N-1);
//         with no request ptr holds. Reset is synchronous, active low.
module rr_arbiter #(
    parameter integer N = 4
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire [N-1:0] req,
    output reg  [N-1:0] grant
);

    localparam integer PW     = (N > 1) ? $clog2(N) : 1;
    localparam integer LAST_I = N - 1;

    // Pointer-width constants, built bit by bit so every width matches.
    wire [PW-1:0] LAST;   // N-1
    wire [PW-1:0] ONE;    // 1

    genvar g;
    generate
        for (g = 0; g < PW; g = g + 1) begin : g_const
            assign LAST[g] = (((LAST_I >> g) & 1) != 0);
            assign ONE[g]  = (g == 0);
        end
    endgenerate

    reg  [PW-1:0] ptr;
    reg  [PW-1:0] ptr_nxt;
    reg  [PW-1:0] winner;
    reg  [PW-1:0] idx;
    reg           any_grant;
    integer       k;

    // Wrapping priority search: first requester at or after ptr wins.
    always @* begin
        grant     = {N{1'b0}};
        winner    = ptr;
        any_grant = 1'b0;
        idx       = ptr;
        for (k = 0; k < N; k = k + 1) begin
            if (!any_grant && req[idx]) begin
                any_grant  = 1'b1;
                grant[idx] = 1'b1;
                winner     = idx;
            end
            if (idx == LAST) idx = {PW{1'b0}};
            else             idx = idx + ONE;
        end
    end

    // One past the winner, wrapping explicitly at N-1.
    always @* begin
        if (winner == LAST) ptr_nxt = {PW{1'b0}};
        else                ptr_nxt = winner + ONE;
    end

    // Pointer register: reset to 0, move only on a grant.
    always @(posedge clk) begin
        if (!rst_n)         ptr <= {PW{1'b0}};
        else if (any_grant) ptr <= ptr_nxt;
    end

`ifdef FORMAL
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    always @(*) begin
        if (!f_past_valid) assume (!rst_n);
    end

    // Upward, wrapping distance from ptr to the winner.
    wire [31:0] f_wdist = (winner >= ptr) ? (winner - ptr) : (winner + N - ptr);

    always @(*) begin
        if (f_past_valid) begin
            assert (ptr <= LAST);
            assert ((grant & (grant - 1'b1)) == {N{1'b0}});
            assert ((grant & ~req) == {N{1'b0}});
            assert ((req == {N{1'b0}}) || (grant != {N{1'b0}}));
            assert (any_grant == (grant != {N{1'b0}}));
            if (any_grant) assert (grant[winner]);
            cover (req == {N{1'b1}});
        end
    end

    always @(posedge clk) begin
        if (f_past_valid) begin
            if (!$past(rst_n))
                assert (ptr == {PW{1'b0}});
            else if ($past(any_grant))
                assert (ptr == (($past(winner) == LAST) ? {PW{1'b0}} : ($past(winner) + ONE)));
            else
                assert (ptr == $past(ptr));
            if ($past(rst_n) && $past(any_grant) && ($past(winner) == LAST))
                cover (ptr == {PW{1'b0}});
        end
    end

    genvar fi;
    generate
        for (fi = 0; fi < N; fi = fi + 1) begin : g_fair
            reg  [7:0]  f_wait;
            wire [31:0] f_dist = (fi >= ptr) ? (fi - ptr) : (fi + N - ptr);

            always @(posedge clk) begin
                if (!rst_n || !req[fi] || grant[fi]) f_wait <= 8'd0;
                else                                  f_wait <= f_wait + 8'd1;
            end

            always @(*) begin
                if (f_past_valid) begin
                    assert (f_wait <= LAST_I);
                    assert (f_wait + f_dist <= LAST_I);
                    if (any_grant && req[fi]) assert (f_wdist <= f_dist);
                    cover (grant[fi]);
                end
            end
        end
    endgenerate
`endif

endmodule
=== END FILE ===
=== FILE: rr_arbiter_tb.v ===
// rr_arbiter_tb.v
// Self-checking testbench for rr_arbiter at N=4 and N=5, side by side.
// Each cycle: grant vs an independent reference pointer model, model-free
// grant properties, per-requester wait bound (fail at N cycles), and
// coverage counters that fail the run if a required case is not reached.
module rr_arbiter_tb;

    reg        clk;
    reg        rst_n;
    reg  [3:0] req4;
    reg  [4:0] req5;
    wire [3:0] grant4;
    wire [4:0] grant5;

    rr_arbiter #(.N(4)) u_arb4 (.clk(clk), .rst_n(rst_n), .req(req4), .grant(grant4));
    rr_arbiter #(.N(5)) u_arb5 (.clk(clk), .rst_n(rst_n), .req(req5), .grant(grant5));

    initial clk = 1'b0;
    always #5 clk = ~clk;

    integer   passed;
    integer   failed;
    integer   cyc;
    integer   nn           [0:1];
    integer   mptr         [0:1];
    integer   wt           [0:15];
    reg       chg          [0:15];
    reg [7:0] prev_r       [0:1];
    integer   cov_none     [0:1];
    integer   cov_all      [0:1];
    integer   cov_fullwait [0:1];
    integer   cov_held     [0:1];
    integer   cov_rst      [0:1];
    integer   cov_alone    [0:15];
    reg       mvalid;
    reg       rot_mode;
    integer   rot_cnt;
    integer   seed;
    integer   ti;
    integer   th;
    integer   ta;
    integer   tk;
    reg [31:0] rnd;
    reg        rv;
    reg [8*64-1:0] nonce;

    // Check one arbiter (index a) for the current cycle, then advance its model.
    task check_arb;
        input integer a;
        input [7:0]   r;
        input [7:0]   g;
        input         rst_v;
        integer   n;
        integer   p;
        integer   pick;
        integer   k;
        integer   j;
        integer   w;
        reg [7:0] expg;
        reg [7:0] allm;
        reg [7:0] bit_k;
        reg       rb;
        reg       gb;
        begin
            n    = nn[a];
            allm = (8'd1 << n) - 8'd1;
            pick = -1;
            p    = 0;
            if (mvalid) begin
                p = mptr[a];
                for (k = n - 1; k >= 0; k = k - 1) begin
                    j = (p + k) % n;
                    if (((r >> j) & 8'd1) != 8'd0) pick = j;
                end
                expg = (pick >= 0) ? (8'd1 << pick) : 8'd0;

                if (g === expg) passed = passed + 1;
                else begin
                    failed = failed + 1;
                    $error("N=%0d cycle %0d: grant %b, reference model expects %b (ptr %0d, req %b)",
                           n, cyc, g, expg, p, r);
                end

                if ((g & ~r) == 8'd0) passed = passed + 1;
                else begin
                    failed = failed + 1;
                    $error("N=%0d cycle %0d: grant %b to a requester that is not asking (req %b)",
                           n, cyc, g, r);
                end

                if ((g & (g - 8'd1)) == 8'd0) passed = passed + 1;
                else begin
                    failed = failed + 1;
                    $error("N=%0d cycle %0d: grant %b is not one-hot or zero", n, cyc, g);
                end

                if ((r == 8'd0) || (g != 8'd0)) passed = passed + 1;
                else begin
                    failed = failed + 1;
                    $error("N=%0d cycle %0d: req %b but no grant (not work conserving)", n, cyc, r);
                end

                if (rot_mode) begin
                    if (g === (8'd1 << (rot_cnt % n))) passed = passed + 1;
                    else begin
                        failed = failed + 1;
                        $error("N=%0d cycle %0d: rotation step %0d granted %b, expected requester %0d",
                               n, cyc, rot_cnt, g, rot_cnt % n);
                    end
                end
            end

            if (!rst_v) begin
                mptr[a] = 0;
                for (k = 0; k < 8; k = k + 1) begin
                    wt[a*8+k]  = 0;
                    chg[a*8+k] = 1'b0;
                end
                if (mvalid && (r != 8'd0)) cov_rst[a] = cov_rst[a] + 1;
            end else if (mvalid) begin
                if (r == 8'd0) cov_none[a] = cov_none[a] + 1;
                if (r == allm) cov_all[a]  = cov_all[a] + 1;
                for (k = 0; k < n; k = k + 1) begin
                    bit_k = 8'd1 << k;
                    rb    = ((r & bit_k) != 8'd0);
                    gb    = ((g & bit_k) != 8'd0);
                    if (r == bit_k) cov_alone[a*8+k] = cov_alone[a*8+k] + 1;
                    if (rb && gb) begin
                        w = wt[a*8+k];
                        if (w <= n - 1) passed = passed + 1;
                        else begin
                            failed = failed + 1;
                            $error("N=%0d cycle %0d: requester %0d granted after waiting %0d cycles",
                                   n, cyc, k, w);
                        end
                        if (w == n - 1) cov_fullwait[a] = cov_fullwait[a] + 1;
                        if ((w > 0) && chg[a*8+k]) cov_held[a] = cov_held[a] + 1;
                        wt[a*8+k]  = 0;
                        chg[a*8+k] = 1'b0;
                    end else if (rb) begin
                        wt[a*8+k] = wt[a*8+k] + 1;
                        if (((r ^ prev_r[a]) & ~bit_k) != 8'd0) chg[a*8+k] = 1'b1;
                        if (wt[a*8+k] == n) begin
                            failed = failed + 1;
                            $error("N=%0d cycle %0d: requester %0d has waited %0d cycles (bound %0d)",
                                   n, cyc, k, n, n - 1);
                        end
                    end else begin
                        wt[a*8+k]  = 0;
                        chg[a*8+k] = 1'b0;
                    end
                end
                if (pick >= 0) mptr[a] = (pick + 1) % n;
            end
            prev_r[a] = r;
        end
    endtask

    // Drive one cycle: inputs change at the falling edge, checks before the rising edge.
    task do_cycle;
        input [7:0] r;
        input       rst_v;
        begin
            @(negedge clk);
            req4  = r[3:0];
            req5  = r[4:0];
            rst_n = rst_v;
            #1;
            check_arb(0, {4'd0, r[3:0]}, {4'd0, grant4}, rst_v);
            check_arb(1, {3'd0, r[4:0]}, {3'd0, grant5}, rst_v);
            if (!rst_v) mvalid = 1'b1;
            cyc = cyc + 1;
        end
    endtask

    // Coverage item: 1 none, 3 all, 4 longest wait, 5 held among changing, 6 reset in traffic, 20+k alone.
    task cov_check;
        input         ok;
        input integer a;
        input integer item;
        begin
            if (ok) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("coverage: N=%0d item %0d was not reached", nn[a], item);
            end
        end
    endtask

    initial begin
        passed   = 0;
        failed   = 0;
        cyc      = 0;
        mvalid   = 1'b0;
        rot_mode = 1'b0;
        rot_cnt  = 0;
        seed     = 32'h1b70baad;
        rnd      = 32'd0;
        rv       = 1'b1;
        nn[0]    = 4;
        nn[1]    = 5;
        for (ta = 0; ta < 2; ta = ta + 1) begin
            mptr[ta]         = 0;
            prev_r[ta]       = 8'd0;
            cov_none[ta]     = 0;
            cov_all[ta]      = 0;
            cov_fullwait[ta] = 0;
            cov_held[ta]     = 0;
            cov_rst[ta]      = 0;
        end
        for (tk = 0; tk < 16; tk = tk + 1) begin
            wt[tk]        = 0;
            chg[tk]       = 1'b0;
            cov_alone[tk] = 0;
        end
        nonce = {64{8'h00}};
        if ($value$plusargs("nirmaan_nonce=%s", nonce) == 0) nonce = {64{8'h00}};

        req4  = 4'd0;
        req5  = 5'd0;
        rst_n = 1'b0;

        // Reset.
        repeat (3) do_cycle(8'h00, 1'b0);

        // No requests: no grant, pointer holds.
        repeat (4) do_cycle(8'h00, 1'b1);

        // Each requester alone.
        for (ti = 0; ti < 5; ti = ti + 1) begin
            do_cycle(8'd1 << ti, 1'b1);
            do_cycle(8'd1 << ti, 1'b1);
        end

        // Everyone requesting after reset: strict rotation 0..N-1, longest wait N-1.
        do_cycle(8'h00, 1'b0);
        rot_mode = 1'b1;
        rot_cnt  = 0;
        for (ti = 0; ti < 20; ti = ti + 1) begin
            do_cycle(8'h1f, 1'b1);
            rot_cnt = rot_cnt + 1;
        end
        rot_mode = 1'b0;

        // A held request among changing others.
        for (th = 0; th < 5; th = th + 1) begin
            for (ti = 0; ti < 12; ti = ti + 1) begin
                rnd = $random(seed);
                do_cycle(rnd[7:0] | (8'd1 << th), 1'b1);
            end
        end

        // Random traffic, drops and re-raises, with reset during traffic.
        for (ti = 0; ti < 400; ti = ti + 1) begin
            rnd = $random(seed);
            if (((ti % 97) == 50) || ((ti % 97) == 51)) rv = 1'b0;
            else                                        rv = 1'b1;
            case (rnd[18:16])
                3'd0:    do_cycle(8'h00, rv);
                3'd1:    do_cycle(8'hff, rv);
                default: do_cycle(rnd[7:0] | rnd[15:8], rv);
            endcase
        end

        // Coverage: every case the interface spec names must have been reached.
        for (ta = 0; ta < 2; ta = ta + 1) begin
            cov_check(cov_none[ta] > 0,     ta, 1);
            cov_check(cov_all[ta] > 0,      ta, 3);
            cov_check(cov_fullwait[ta] > 0, ta, 4);
            cov_check(cov_held[ta] > 0,     ta, 5);
            cov_check(cov_rst[ta] > 0,      ta, 6);
            for (tk = 0; tk < nn[ta]; tk = tk + 1)
                cov_check(cov_alone[ta*8+tk] > 0, ta, 20 + tk);
        end

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule
=== END FILE ===
